-- Shared helpers for snes/test/audio/*.lua (prepended by run.mjs).
-- The prelude defines UPLOAD (path of dist/snes/gen/audio/upload.bin) and
-- the cue ids (AUDIO_*) generated by snes/gen/audio.mjs.
AU = 0x7EDD00
AU_TEST = AU + 0x16
local failures = 0
function check(name, ok, detail)
  if ok then H.result(name, 'pass') else
    failures = failures + 1
    H.result(name, 'FAIL ' .. tostring(detail or ''))
  end
  return ok
end
function finish() H.result('failures', failures) end
function aram(a) return emu.read(a, emu.memType.spcRam) end
function dsp(r) return emu.read(r, emu.memType.spcDspRegisters) end
function port3() return aram(0xE6) end   -- the status byte the SPC publishes on port 3
-- Mailbox op | arg<<8 (snes/src/modules/audio/module.asm audio_test_poll).
function cmd(op, arg) H.w8(AU_TEST + 1, arg or 0); H.w8(AU_TEST, op) end

-- Write the current extension (segments and driver patches from upload.bin)
-- into ARAM right after a state loads, before any frame runs: states saved by
-- other builds then run today's extension. The SPC is in driver code at any
-- instruction boundary (the extension regions are unused by the driver).
function injectExtension()
  local f = assert(io.open(UPLOAD, 'rb'))
  local data = f:read('*a')
  f:close()
  -- the module as if it had been running: no song change pending, no hold-off
  H.w8(AU + 0x3F, H.r8(0x7E1E05))
  H.w8(AU + 0x1F, 0)
  local i = 1
  while i + 3 <= #data do
    local addr = data:byte(i) | (data:byte(i + 1) << 8)
    local len = data:byte(i + 2) | (data:byte(i + 3) << 8)
    if len == 0 then return true end
    for k = 0, len - 1 do emu.write(addr + k, data:byte(i + 4 + k), emu.memType.spcRam) end
    i = i + 4 + len
  end
  return false
end

-- First ARAM byte that differs from the extension's code segments (the
-- variable tables at $1818, $1930 and DP $E3 are left out), or nil.
function extensionDamage()
  local f = assert(io.open(UPLOAD, 'rb'))
  local data = f:read('*a')
  f:close()
  local i = 1
  while i + 3 <= #data do
    local addr = data:byte(i) | (data:byte(i + 1) << 8)
    local len = data:byte(i + 2) | (data:byte(i + 3) << 8)
    if len == 0 then return nil end
    if addr ~= 0x1818 and addr ~= 0x1930 and addr ~= 0x00E3 then
      for k = 0, len - 1 do
        if aram(addr + k) ~= data:byte(i + 4 + k) then return addr + k end
      end
    end
    i = i + 4 + len
  end
  return nil
end
-- First byte of the native effect samples ($4800-$4DF0, boot chunk C3:1AE2)
-- that differs from the cartridge, or nil.
function effectSampleDamage()
  local n = H.r8(0xC31AE2) | (H.r8(0xC31AE3) << 8)
  for k = 0, n - 1 do
    if aram(0x4800 + k) ~= H.r8(0xC31AE4 + k) then return 0x4800 + k end
  end
  return nil
end
function customDamage()
  if not CUSTOM then return nil end
  local f=assert(io.open(UPLOAD,'rb'));local data=f:read('*a');f:close()
  local i=1
  while i+3<=#data do
    local a=data:byte(i)|(data:byte(i+1)<<8);local n=data:byte(i+2)|(data:byte(i+3)<<8)
    if n==0 then break end
    if a==0x4DF1 or a==0x0180 or a==0x183E or a==0x18BE or a==0x197C or a==0x1860 or a==0x18E0 or a==0x19C0 or a==0x19D0 or a==0x0BED or a==0x0E10 or a==0x0C48 or a==0x14B4 or a==0xFFFB then
      for j=0,n-1 do if aram(a+j)~=data:byte(i+4+j) then return string.format('%04X',a+j) end end
    end
    i=i+4+n
  end
  return nil
end

-- Per-frame DSP view of one voice: SRCN, ENVX, OUTX (signed).
function voiceState(v)
  local o = dsp(v * 16 + 9)
  if o >= 128 then o = o - 256 end
  return { srcn = dsp(v * 16 + 4), envx = dsp(v * 16 + 8), outx = o,
           voll = dsp(v * 16), pitch = dsp(v * 16 + 2) | (dsp(v * 16 + 3) << 8) }
end
function voicesEnv()
  local t = {}
  for v = 0, 7 do t[#t + 1] = dsp(v * 16 + 8) end
  return t
end
